            if (root.TryGetProperty("Abstract", out var abs) && abs.GetString() is { Length: > 0 } abstractText)
            {
                var source = root.TryGetProperty("AbstractSource", out var src) ? src.GetString() : "Unknown";
                var link = root.TryGetProperty("AbstractURL", out var aurl) ? aurl.GetString() : "";
                results.Add($"[{source}] {abstractText}\n  URL: {link}");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics) && topics.ValueKind == JsonValueKind.Array)
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                    {
                        var topicUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : "";
                        results.Add($"• {t}\n  URL: {topicUrl}");
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : "No results found for this query. Try rephrasing.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Save a research note. Use this to record key findings, facts, or insights discovered during research.")]
    public static string SaveNote(
        [Description("The note content to save")] string note)
    {
        s_notes.Add(note);
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📝 Note #{s_notes.Count} saved ({note.Length} chars)");
        Console.ResetColor();
        return $"Note #{s_notes.Count} saved successfully.";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public static string GetNotes()
    {
        if (s_notes.Count == 0)
            return "No notes saved yet.";

        var formatted = s_notes.Select((n, i) => $"[Note #{i + 1}]\n{n}");
        return string.Join("\n\n", formatted);
    }
}

// --- Main program ---

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔬 AI Research Agent           ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

// Resolve API key and model from environment.
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY");
if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.ForegroundColor = ConsoleColor.Red;
    Console.WriteLine("Error: Set the OPENAI_API_KEY environment variable.");
    Console.ResetColor();
    return 1;
}

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = new[]
{
    AIFunctionFactory.Create(ResearchTools.WebSearch),
    AIFunctionFactory.Create(ResearchTools.SaveNote),
    AIFunctionFactory.Create(ResearchTools.GetNotes),
};

var chatOptions = new ChatOptions { Tools = [.. tools] };

// Get the research topic.
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return 1;
}

Console.WriteLine();
Console.ForegroundColor = ConsoleColor.Green;
Console.WriteLine($"Researching: {topic}");
Console.ResetColor();
Console.WriteLine(new string('─', 50));

var systemPrompt = """
    You are a thorough research agent. Given a topic, you:
    1. Search the web multiple times with varied queries to gather broad information.
    2. Save important findings as notes using the SaveNote tool.
    3. After gathering enough information, retrieve your notes and produce a well-structured summary.

    Always perform at least 2-3 different searches to get diverse perspectives.
    Save key facts and findings as notes as you go.
    End with a comprehensive summary that synthesizes all your research.
    """;

List<ChatMessage> messages =
[
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}"),
];

var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine();
Console.WriteLine(new string('═', 50));
Console.ForegroundColor = ConsoleColor.Cyan;
Console.WriteLine("📋 RESEARCH SUMMARY");
Console.ResetColor();
Console.WriteLine(new string('═', 50));
Console.WriteLine();
Console.WriteLine(response.Text);
Console.WriteLine();

return 0;

